using UnityEngine;
using Xunit;

namespace OniBrutal.Tests
{
    /// Matrix4x4's projection and look-at builders and Quaternion.AngleAxis against the original
    /// player (tools/UnityProbe ProjectionMath.cs, PROBE_SCENARIO=projection; pj-check.py rule
    /// reproduces every logged case): a few random cases of each and all the degenerate ones
    /// (equal planes, zero sizes, fields of view of 0, 180 and 360 degrees, NaN, infinity, and
    /// the boundaries where LookAt and AngleAxis fall back to the identity). Float bits in hex,
    /// matrices row-major.
    public class ProjectionTests
    {
        static float[] Bits(string hex) => System.Array.ConvertAll(hex.Split(','), h => System.BitConverter.Int32BitsToSingle(System.Convert.ToInt32(h, 16)));

        static string Hex(params float[] v) => string.Join(",", System.Array.ConvertAll(v, f => System.BitConverter.SingleToInt32Bits(f).ToString("x8")));

        static string Hex(Matrix4x4 m)
        {
            var e = new float[16];
            for (int i = 0; i < 16; i++) e[i] = m[i / 4, i % 4];
            return Hex(e);
        }

