        public void LookAtIsTheOriginals(string input, string expected)
        {
            var v = Bits(input);
            var m = Matrix4x4.LookAt(new Vector3(v[0], v[1], v[2]), new Vector3(v[3], v[4], v[5]), new Vector3(v[6], v[7], v[8]));
            Assert.Equal(expected, Hex(m));
        }

